import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

CACHE_FILE = '.stats_cache'

def load_cache():
    cache = {}
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, 'r') as f:
            for line in f:
                path, size, line_count, mod_time = line.strip().split('\t')
                cache[Path(path).absolute()] = {
                    'size': int(size),
                    'line_count': int(line_count),
                    'mod_time': float(mod_time)
                }
    return cache

def save_cache(cache):
    with open(CACHE_FILE, 'w') as f:
        for path, stats in cache.items():
            f.write(f"{path.relative_to(Path.cwd()).as_posix()}\t"
                    f"{stats['size']}\t{stats['line_count']}\t{stats['mod_time']}\n")

def get_file_stats(path):
    try:
        with open(path, 'rb') as f:
            size = f.tell()
            f.seek(0)
            last_byte = None
            line_count = 0
            for line in f:
                line_count += 1
                last_byte = line[-1] if line else None
            if last_byte != b'\n':
                line_count += 1
            return size, line_count
    except (IOError, OSError):
        return None, None

def process_path(path):
    abs_path = Path(path).absolute()
    if abs_path in cache:
        cached = cache[abs_path]
        if os.path.getmtime(abs_path) == cached['mod_time']:
            print(f"{path}\t{cached['size']}\t{cached['line_count']}")
            return
    size, line_count = get_file_stats(abs_path)
    if size is not None:
        cache[abs_path] = {
            'size': size,
            'line_count': line_count,
            'mod_time': os.path.getmtime(abs_path)
        }
        print(f"{path}\t{size}\t{line_count}")
    else:
        print(f"{path}\tERROR")

def main():
    global cache
    cache = load_cache()
    paths = []
    for line in sys.stdin:
        path = line.strip()
        if path:
            paths.append(path)

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(process_path, path): path for path in paths}
        for future in as_completed(futures):
            pass
    save_cache(cache)

if __name__ == "__main__":
    main()

import os
import sys
from pathlib import Path

class StatsCache:
    def __init__(self):
        self.cache = {}
        self.cache_file = '.stats_cache'

    def load(self):
        try:
            with open(self.cache_file, 'r') as f:
                for line in f:
                    path, size, lines = line.strip().split('\t')
                    self.cache[Path(path).absolute()] = (int(size), int(lines))
        except (FileNotFoundError, ValueError):
            pass

    def save(self):
        with open(self.cache_file, 'w') as f:
            for path, (size, lines) in sorted(self.cache.items()):
                f.write(f"{path.absolute()}\t{size}\t{lines}\n")

def compute_stats(path):
    try:
        with open(path, 'rb') as f:
            size = f.tell()
            content = f.read()
            lines = content.count(b'\n') + (1 if content and content[-1] != b'\n' else 0)
            return (size, lines)
    except (IOError, OSError):
        return (None, None)

def process_paths():
    cache = StatsCache()
    cache.load()

    while True:
        group = []
        for _ in range(4):
            line = sys.stdin.readline()
            if not line:
                break
            path_str = line.strip()
            if not path_str:
                continue
            path = Path(path_str).absolute()
            if path in cache.cache:
                size, lines = cache.cache[path]
                print(f"{path_str}\t{size}\t{lines}")
                continue
            group.append(path)

        for path in group:
            size, lines = compute_stats(path)
            if size is None:
                print(f"{path_str}\tERROR")
            else:
                print(f"{path_str}\t{size}\t{lines}")
                cache.cache[path] = (size, lines)

        if not group:
            break

    cache.save()

if __name__ == "__main__":
    process_paths()

