import os
import sys
from pathlib import Path

def main():
    cache_file = '.stats_cache'
    cache = {}

    # Load cache if it exists
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            for line in f:
                path, size = line.strip().split('\t')
                cache[path] = int(size)

    input_paths = []
    while True:
        try:
            path = sys.stdin.readline().strip()
            if not path:
                break
            input_paths.append(path)
        except EOFError:
            break

    # Process input paths in groups of up to 4
    for i in range(0, len(input_paths), 4):
        group = input_paths[i:i+4]
        for path in group:
            if path in cache:
                print(f"{path}\t{cache[path]}")
            else:
                try:
                    with open(path, 'rb') as f:
                        size = os.fstat(f.fileno()).st_size
                        cache[path] = size
                        print(f"{path}\t{size}")
                except (IOError, OSError):
                    print(f"{path}\tERROR")

    # Write cache back to file
    with open(cache_file, 'w') as f:
        for path, size in sorted(cache.items()):
            f.write(f"{path}\t{size}\n")

if __name__ == "__main__":
    main()
